select energy_manager.load_cards($cards$[
{"id":"p4-b04-034","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"Exercise L-1: hot water at 10 kg/min cools from 70 °C to 50 °C, cold water at 25 kg/min enters at 25 °C (Cp 4.179 kJ/kg·K). U = 800 W/m²·K, fouling neglected. What area does a counter-flow exchanger need?","back":"About 0.57 m² (duty about 13,930 W, cold outlet 33 °C, LMTD 30.6 °C).","explain":"This is chapter exercise L-1. The answer is worked here from the chapter method and is not printed in the book. Parallel flow would need about 0.61 m² for the same duty.","flash":false,"source":"BEE Book 4 Ch 04 p101","steps":[{"prompt":"Calculate the duty.","answer":"(10 ÷ 60) × 4.179 × 1000 × (70 − 50) = 13,930 W","explain":"Hot flow times Cp times temperature drop."},{"prompt":"Find the cold outlet temperature.","answer":"25 + 13,930 ÷ (4.179 × 1000 × 25 ÷ 60) = 25 + 8 = 33 °C","explain":"Cold water picks up the same heat."},{"prompt":"Find the counter-flow end differences.","answer":"70 − 33 = 37 °C; 50 − 25 = 25 °C","explain":"Hot inlet with cold outlet; hot outlet with cold inlet."},{"prompt":"Calculate the area.","answer":"LMTD = (37 − 25) ÷ ln(37 ÷ 25) = 30.6 °C; area = 13,930 ÷ (800 × 30.6) = 0.57 m²","explain":"Area is duty divided by U times LMTD."}],"order":4233},
{"id":"p4-b04-035","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"Chapter question S-7: a counter-flow exchanger has the hot stream entering at 70 °C and leaving at 55 °C, and the cold stream entering at 30 °C and leaving at 55 °C. What is the LMTD?","back":"About 19.6 °C.","explain":"This is chapter question S-7, worked by the book's LMTD method. Counter-flow pairs the hot inlet with the cold outlet, giving end differences of 15 °C and 25 °C.","flash":false,"source":"BEE Book 4 Ch 04 p101","steps":[{"prompt":"Write the LMTD formula.","answer":"LMTD = (ΔT1 − ΔT2) ÷ ln(ΔT1 ÷ ΔT2)","explain":"Two end differences of the exchanger, taken at each end."},{"prompt":"Find the two end differences.","answer":"70 − 55 = 15 °C (hot in − cold out); 55 − 30 = 25 °C (hot out − cold in)","explain":"Counter-flow end pairing."},{"prompt":"Calculate the LMTD.","answer":"(25 − 15) ÷ ln(25 ÷ 15) = 10 ÷ 0.5108 = 19.6 °C","explain":"Logarithmic mean of the two end differences."}],"order":4234},
{"id":"p4-b05-001","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Between what loading range is an induction motor's efficiency almost constant, and where does the saving opportunity lie?","back":"Efficiency stays almost constant from about 50% to 100% loading. The saving opportunity lies mainly in selecting the right motor and using it well.","explain":"Figure 5.1 shows this flat efficiency curve. A motor rated above what the equipment needs runs at part load, where efficiency falls. Right-sizing is therefore the main lever.","flash":true,"source":"BEE Book 4 Ch 05 p105","order":4235},
{"id":"p4-b05-002","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"When is replacing an underloaded motor with a smaller motor generally most economical?","back":"For larger motors running at less than about one-third to one-half of their capacity. The exact threshold depends on motor size. A smaller motor then runs fully loaded at higher efficiency.","explain":"The book says this is generally most economical for larger motors. Check the motor's size and measured loading before deciding.","flash":false,"source":"BEE Book 4 Ch 05 p105","order":4236},
{"id":"p4-b05-003","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"How is motor efficiency defined in the chapter?","back":"Efficiency = Pout ÷ Pin, where Pout is output power, Pin is input power, and the difference between them is the losses (Ploss) inside the motor.","explain":"Because losses make up the gap between input and output, a lower efficiency means more input power for the same shaft output.","flash":false,"source":"BEE Book 4 Ch 05 p105","order":4237},
{"id":"p4-b05-004","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What is motor loading, and how is loading percentage defined?","back":"Motor loading is the actual operating load of the motor. Loading % = (actual load ÷ rated capacity of the motor) × 100.","explain":"Loading % shows whether a motor is oversized. Rated capacity is the nameplate output, so the percentage is relative to that figure.","flash":false,"source":"BEE Book 4 Ch 05 p105","order":4238},
{"id":"p4-b05-005","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Name the three motor efficiency test standards the book lists, and the maximum spread between them.","back":"IEC 60034-2 (and the newer IEC 61972) in Europe; IEEE 112 Method B in the US; JEC 37 in Japan. Efficiency values can differ by up to 3% between them.","explain":"Efficiency testing needs extensive facilities. Because the standards differ, a test value should always be quoted with the standard it was based on.","flash":true,"source":"BEE Book 4 Ch 05 p106","order":4239},
{"id":"p4-b05-006","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"When may nameplate efficiency be used for calculations?","back":"When the motor load is in the range of 50% to 100%.","explain":"The book allows nameplate efficiency in this range for simplicity, because measuring efficiency is laborious.","flash":false,"source":"BEE Book 4 Ch 05 p106","order":4240},
{"id":"p4-b05-007","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"In a no-load test, how are core loss and friction-and-windage (F&W) loss found?","back":"Core plus F&W loss = no-load power (W) − (no-load current)² × stator resistance. Repeating the test at several voltages and plotting no-load kW against voltage, the intercept gives the F&W component.","explain":"No-load power factor is very low, so low-PF wattmeters are needed. The stator I²R loss is subtracted before the core and F&W split is made.","flash":false,"source":"BEE Book 4 Ch 05 p106","order":4241},
{"id":"p4-b05-008","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Why is stator resistance corrected to operating temperature, and what is the correction formula?","back":"Modern motors operate around 100–120 °C. R₂ = R₁ × (235 + t₂) ÷ (235 + t₁), where t₁ is ambient and t₂ is operating temperature, both in °C.","explain":"The book warns that correcting only to 75 °C may be inaccurate for modern motors. Stator I²R losses are then calculated with the corrected resistance.","flash":false,"source":"BEE Book 4 Ch 05 p106","order":4242},
{"id":"p4-b05-009","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"How are rotor I²R losses estimated in the field, and how is slip measured?","back":"Rotor I²R loss = slip × (stator input − stator I²R loss − core loss). Slip is measured with a stroboscope or non-contact tachometer and corrected to operating temperature.","explain":"Rotor loss is tied to slip, so an accurate slip reading matters. The book measures rotor losses this way rather than from rotor resistance.","flash":false,"source":"BEE Book 4 Ch 05 p106","order":4243},
{"id":"p4-b05-010","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What stray-load loss do IS and IEC standards assume, and what range does IEEE 112 give?","back":"IS and IEC assume a fixed 0.5% of output. IEEE 112 gives 0.9% to 1.8%. The book notes actual stray losses are likely to be higher.","explain":"Stray losses are hard to measure even on test beds. The book's comments say actual stray loss for motors up to 200 HP is likely 1% to 3%, so the 0.5% assumption can understate losses.","flash":true,"source":"BEE Book 4 Ch 05 p107","order":4244},
{"id":"p4-b05-011","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What stray-load loss percentage does the book give for each motor size band?","back":"1–125 HP: 1.8%. 125–500 HP: 1.5%. 501–2499 HP: 1.2%. 2500 HP and above: 0.9%.","explain":"Stray loss percentage falls as motor size rises. Use these values for estimates, because measuring stray loss directly is impractical on the shop floor.","flash":false,"source":"BEE Book 4 Ch 05 p107","order":4245},
{"id":"p4-b05-012","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Why is an accurate field efficiency figure hard to obtain?","back":"The same motor tested by different methods, or by the same method at different manufacturers, can differ by about 2% in efficiency.","explain":"Stray load losses cannot be measured accurately, and the IEEE method is rarely used on the shop floor. Field efficiency values are therefore approximate.","flash":false,"source":"BEE Book 4 Ch 05 p107","order":4246},
{"id":"p4-b05-013","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Name the loss components in the book's field method for estimating motor efficiency.","back":"(1) Stator I²R, from stator resistance corrected to operating temperature and rated current. (2) Rotor I²R, from slip (rated speed and output). (3) Core and F&W losses, from the no-load test. (4) Stray load loss, assumed.","explain":"The book's worked example then adds these losses to output to get input power, and divides output by input to get efficiency.","flash":false,"source":"BEE Book 4 Ch 05 p107","order":4247},
{"id":"p4-b05-014","paper":4,"topic":"Motor Performance and VSD","kind":"problem","front":"A 34 kW, 415 V, 57 A, 1475 rpm, delta-connected motor (frame LD 200 L) has these data: no-load test at 415 V, 16.1 A, 50 Hz, 1063.74 W; stator resistance 0.264 Ω per phase at 30 °C. Find the full-load efficiency and full-load power factor.","back":"Full-load efficiency ≈ 92.2%. Full-load PF ≈ 0.90. Full-load input ≈ 36.9 kW.","explain":"This is the book's worked example for field efficiency estimation. The stray loss and slip are assumptions, so the result is an estimate.","flash":false,"source":"BEE Book 4 Ch 05 p108","steps":[{"prompt":"Find the iron plus friction-and-windage loss at no load.","answer":"Stator Cu at 30 °C = 3 × (16.1 ÷ √3)² × 0.264 = 68.43 W. Iron + F&W = 1063.74 − 68.43 = 995.3 W.","explain":"Core and F&W losses are the no-load power minus the no-load stator copper loss."},{"prompt":"Correct the stator resistance to 120 °C.","answer":"R₁₂₀ = 0.264 × (120 + 235) ÷ (30 + 235) = 0.354 Ω per phase.","explain":"Modern motors run at 100–120 °C, so the book corrects to that temperature."},{"prompt":"Compute the full-load stator copper loss at 120 °C.","answer":"3 × (57 ÷ √3)² × 0.354 = 1150.1 W.","explain":"Full-load current is 57 A, so the I²R loss uses the corrected resistance."},{"prompt":"Find the full-load slip and the rotor input.","answer":"Slip = (1500 − 1475) ÷ 1500 = 0.0167. Rotor input = 34000 ÷ (1 − 0.0167) = 34577.4 W.","explain":"The book derives rotor input from rated output and slip, using the synchronous speed of 1500 rpm."},{"prompt":"Add the stray load loss at 0.5% of rated output.","answer":"0.005 × 34000 = 170 W.","explain":"IS and IEC standards fix stray loss at 0.5% of output, which the book uses as an assumption."},{"prompt":"Find total input, full-load efficiency and power factor.","answer":"Input = 34577.4 + 1150.1 + 995.3 + 170 = 36892.8 W. η = 34000 ÷ 36892.8 = 92.2%. PF = 36892.8 ÷ (√3 × 415 × 57) = 0.90.","explain":"The book notes stray losses are likely higher than 0.5% and nameplate slip is not accurate, so treat the result as an estimate."}],"order":4248},
{"id":"p4-b05-015","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What are the three methods the chapter gives for estimating motor loading?","back":"(1) Input power measurement, using rated kW ÷ full-load efficiency as rated input. (2) Line current, valid up to about 75% load. (3) Slip method with a tachometer, optionally voltage-compensated.","explain":"The book calls the speed/slip method often favoured for its simplicity and safety, though its accuracy is limited.","flash":true,"source":"BEE Book 4 Ch 05 p110","order":4249},
{"id":"p4-b05-016","paper":4,"topic":"Motor Performance and VSD","kind":"problem","front":"A 15 kW motor has nameplate efficiency 0.9. A power meter reads 8 kW of input. What is the motor loading?","back":"About 48%.","explain":"The book uses this as its worked example for the input power method. Measured input is compared with the rated input, not the rated output.","flash":false,"source":"BEE Book 4 Ch 05 p111","steps":[{"prompt":"Find the rated input power at full load.","answer":"P_ir = 15 ÷ 0.9 = 16.7 kW.","explain":"Nameplate kW is output, so convert it to input before comparing with the measured value."},{"prompt":"Compute the percentage loading.","answer":"Loading = 8 ÷ 16.7 × 100 = 48%.","explain":"Measured input power is divided by rated input power."},{"prompt":"Check the result against the efficiency rule.","answer":"48% is just below the 50–100% band in which nameplate efficiency may be used, so measured efficiency gives a more accurate figure.","explain":"Outside the 50–100% band the book's simplification is less safe, so measured efficiency is preferred."}],"order":4250},
{"id":"p4-b05-017","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Why is the line-current method not valid below about 75% load?","back":"Below 75% load, power factor degrades and the amperage curve becomes non-linear, so current is not a useful load indicator.","explain":"The book allows the line-current method only as a preliminary check to identify oversized motors.","flash":false,"source":"BEE Book 4 Ch 05 p111","order":4251},
{"id":"p4-b05-018","paper":4,"topic":"Motor Performance and VSD","kind":"problem","front":"A 7.5 kW motor has nameplate full-load speed 1450 rpm. On a 50 Hz, 4-pole supply (synchronous speed 1500 rpm) it runs at 1480 rpm. What is its load and actual output?","back":"40% load, so about 3 kW output.","explain":"The book's slip-method example. Nameplate slip represents full load, so the measured slip is compared with it.","flash":false,"source":"BEE Book 4 Ch 05 p112","steps":[{"prompt":"Find the nameplate slip (full load).","answer":"1500 − 1450 = 50 rpm.","explain":"Nameplate slip is the synchronous speed minus the nameplate full-load speed."},{"prompt":"Find the measured slip.","answer":"1500 − 1480 = 20 rpm.","explain":"Measured slip is the synchronous speed minus the speed measured in the field."},{"prompt":"Compute the percentage load.","answer":"Load = 20 ÷ 50 × 100 = 40%.","explain":"Slip is proportional to load, so the ratio of slips gives the load fraction."},{"prompt":"Convert to output power.","answer":"0.40 × 7.5 kW = 3 kW.","explain":"Load % applies to the rated power."}],"order":4252},
{"id":"p4-b05-019","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What is the main source of error in the slip method of estimating motor load?","back":"The nameplate full-load speed, which manufacturers round to multiples of 5 rpm. With a 40 rpm correct slip, a 5 rpm error changes the calculated load by about 12%.","explain":"The method relies on the gap between nameplate full-load speed and synchronous speed, so a small speed error becomes a large load error.","flash":false,"source":"BEE Book 4 Ch 05 p112","order":4253},
{"id":"p4-b05-020","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"How does the voltage-compensated slip formula correct for voltage?","back":"Load % = Slip ÷ [(Ss − Sn) × (Vr ÷ V)²] × 100, where Ss is synchronous speed, Sn is nameplate full-load speed, Vr is nameplate voltage and V is measured RMS line voltage.","explain":"Slip varies inversely with terminal voltage squared, so a motor at low voltage slips more. The correction keeps the load estimate fair.","flash":false,"source":"BEE Book 4 Ch 05 p112","order":4254},
{"id":"p4-b05-021","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"How can rewind quality be judged without a full before-and-after efficiency test?","back":"Keep a log of no-load input current for each motor. It rises with poor-quality rewinds. Also review the rewind shop's procedure. Using smaller-diameter wire raises resistance and I²R losses.","explain":"The book says ideally efficiency should be compared before and after rewinding, but the no-load current log is the simpler check.","flash":false,"source":"BEE Book 4 Ch 05 p112","order":4255},
{"id":"p4-b05-022","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What is the formula for synchronous speed, and what speed does a 4-pole motor run at on 50 Hz?","back":"Synchronous speed = 120 × f ÷ p rpm, where f is frequency in Hz and p is the number of poles. A 4-pole motor on 50 Hz runs at a synchronous speed of 1500 rpm.","explain":"Speed changes in direct proportion to frequency, and the number of poles in the stator also sets it. The book's slip calculations start from this synchronous speed.","flash":false,"source":"BEE Book 4 Ch 05 p114","order":4256},
{"id":"p4-b05-023","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What are the two basic components of a variable frequency drive, and what does each do?","back":"A rectifier converts the 50 Hz AC supply to DC. An inverter, fed from the DC bus, converts it back to AC at the frequency needed for the desired shaft speed.","explain":"The DC bus acts as a parking lot for the DC voltage. The two basic functions of a VSD are power conversion from one frequency to another and control of the output frequency.","flash":false,"source":"BEE Book 4 Ch 05 p114","order":4257},
{"id":"p4-b05-024","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Why do variable torque drives save energy on fans and pumps?","back":"A fan needs much less torque at 50% speed than at full speed. A variable torque drive applies only the torque needed, so energy use falls.","explain":"Energy saving is usually the main motive for variable torque drives on centrifugal loads, as the book states.","flash":false,"source":"BEE Book 4 Ch 05 p115","order":4258},
{"id":"p4-b05-025","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Which applications need constant torque VFDs rather than variable torque drives?","back":"Conveyors, positive displacement pumps, punch presses, extruders and similar applications needing a constant level of torque at all speeds.","explain":"Centrifugal fans and pumps are variable torque loads. Picking the wrong type affects the overload rating needed.","flash":false,"source":"BEE Book 4 Ch 05 p115","order":4259},
{"id":"p4-b05-026","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What overload capacity should constant torque and variable torque VFDs provide for one minute?","back":"Constant torque: 150% or more for one minute. Variable torque: 120% for one minute.","explain":"Centrifugal applications rarely exceed rated current, so variable torque drives need less overload capacity.","flash":true,"source":"BEE Book 4 Ch 05 p115","order":4260},
{"id":"p4-b05-027","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What is the lowest speed a motor should run at without auxiliary cooling?","back":"Not below 20% of its specified maximum speed. Below that it overheats unless auxiliary cooling is fitted.","explain":"The book says auxiliary motor cooling should be used if the motor must run at very slow speeds.","flash":false,"source":"BEE Book 4 Ch 05 p115","order":4261},
{"id":"p4-b05-028","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"How do you size one VFD for several motors, and why is horsepower not used?","back":"Add the full-load amp ratings of all motors. All motors on the drive must have the same voltage rating. Horsepower is an inaccurate basis for sizing a VFD.","explain":"The book's sizing basis is full-load amperage, so motor HP should not be used.","flash":false,"source":"BEE Book 4 Ch 05 p115","order":4262},
{"id":"p4-b05-029","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What efficiency and true system power factor should a VFD offer?","back":"Efficiency of 95% or better at full load, and a true system power factor of 0.95 or better.","explain":"These are the book's selection benchmarks for a VFD. The OCR of this passage is cut off, so check the book page before quoting the power factor condition.","flash":true,"source":"BEE Book 4 Ch 05 p116","order":4263},
{"id":"p4-b05-030","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What protections does the book require a VFD to have?","back":"Motor overload protection (instantaneous trip) and motor overcurrent protection. Additional protection: over and under voltage, over temperature, ground fault, and control or microprocessor fault.","explain":"The book separates basic motor protection from additional protective circuits that give an orderly shutdown and indicate the fault.","flash":false,"source":"BEE Book 4 Ch 05 p116","order":4264},
{"id":"p4-b05-031","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"How should a VFD respond to a fault, and how does it restart after a power loss?","back":"It shuts down in an orderly way, indicates the fault, and needs a manual reset (except for under-voltage). Under-voltage from a power loss restarts automatically when power returns. Its memory keeps the previous three faults.","explain":"These behaviours are the book's requirements for protection and power quality. The fault history is kept for later review.","flash":true,"source":"BEE Book 4 Ch 05 p116","order":4265},
{"id":"p4-b05-032","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What extra protection does a built-up VFD system need?","back":"Externally operated short-circuit protection, a door-interlocked fused disconnect, and a circuit breaker or motor circuit protector (MCP).","explain":"The book lists these for systems assembled from separate components, in addition to the drive's own protection.","flash":false,"source":"BEE Book 4 Ch 05 p116","order":4266},
{"id":"p4-b05-033","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"What is the first step in judging whether a load suits a VSD?","back":"Find the equipment's operating hours at each load condition, using a power analyzer with continuous data storage or a simple energy meter read periodically.","explain":"The load must vary to justify a VSD. Figure 5.3 shows an excellent candidate and Figure 5.4 a poor one.","flash":false,"source":"BEE Book 4 Ch 05 p116","order":4267},
{"id":"p4-b05-034","paper":4,"topic":"Motor Performance and VSD","kind":"fact","front":"Name the four groups of information the book lists for evaluating VSD energy savings.","back":"(1) The flow control method being compared (throttling or dampers, recirculation, eddy-current coupling, inlet guide vanes, two-speed motor). (2) Pump or fan curves and efficiency. (3) Process data (specific gravity or density, system resistance curve, duty cycle). (4) Efficiency of electrical equipment (motors, VSDs, gears, transformers).","explain":"Where precise data is missing for points 2 and 4, the book allows reasonable assumptions.","flash":false,"source":"BEE Book 4 Ch 05 p117","order":4268},
{"id":"p4-b05-035","paper":4,"topic":"Motor Performance and VSD","kind":"problem","front":"A 75 kW, 4-pole induction motor operates at 49.8 Hz. Its rating is 415 V and 1440 rpm. The measured speed is 1470 rpm and the applied voltage is 428 V. What is the percentage loading?","back":"About 47.3% loading.","explain":"The book's voltage-compensated slip example. The voltage term corrects for the supply running above rated voltage.","flash":false,"source":"BEE Book 4 Ch 05 p118","steps":[{"prompt":"Find the synchronous speed at 49.8 Hz.","answer":"Ss = 120 × 49.8 ÷ 4 = 1494 rpm.","explain":"Synchronous speed depends on frequency and the number of poles."},{"prompt":"Find the measured slip.","answer":"Slip = 1494 − 1470 = 24 rpm.","explain":"Slip is synchronous speed minus measured speed."},{"prompt":"Find the nameplate slip.","answer":"Ss − Sn = 1494 − 1440 = 54 rpm.","explain":"The nameplate slip is the full-load slip the motor is rated for."},{"prompt":"Find the voltage correction factor.","answer":"(Vr ÷ V)² = (415 ÷ 428)² = 0.940.","explain":"Slip varies inversely with voltage squared, so this factor adjusts the denominator."},{"prompt":"Compute the load.","answer":"Load = 24 ÷ (54 × 0.940) × 100 = 47.27%.","explain":"Slip load divided by the voltage-corrected nameplate slip gives the fraction of rated output."}],"order":4269},
{"id":"p4-b05-036","paper":4,"topic":"Motor Performance and VSD","kind":"problem","front":"A 6-pole, 415 V, 50 Hz motor delivers 22 kW at the rotor shaft at 950 rpm, power factor 0.88. Total stator loss (core, copper and other) is 2 kW. Find the slip, rotor copper loss, total input, line current and operating efficiency.","back":"Slip 5%. Rotor copper loss ≈ 1.16 kW. Total input 25.16 kW. Line current ≈ 39.75 A. Efficiency ≈ 87.4%.","explain":"The book's second solved example. Rotor copper loss equals slip times rotor input, and it also equals rotor input minus output.","flash":false,"source":"BEE Book 4 Ch 05 p118","steps":[{"prompt":"Find the synchronous speed and slip.","answer":"Ss = 120 × 50 ÷ 6 = 1000 rpm. Slip = (1000 − 950) ÷ 1000 = 5%.","explain":"A 6-pole motor on 50 Hz has a synchronous speed of 1000 rpm."},{"prompt":"Find rotor input and rotor copper loss.","answer":"Rotor input = 22 ÷ (1 − 0.05) = 23.16 kW. Rotor Cu loss = 0.05 × 23.16 = 1.16 kW.","explain":"Rotor copper loss is the slip times rotor input, which equals rotor input minus output."},{"prompt":"Find the total input to the motor.","answer":"23.16 + 2 = 25.16 kW.","explain":"The stator loss of 2 kW is added to the rotor input."},{"prompt":"Find the line current at 415 V and PF 0.88.","answer":"I = 25.16 × 1000 ÷ (√3 × 415 × 0.88) ≈ 39.75 A (book value).","explain":"Three-phase current is input power divided by √3 × V × PF."},{"prompt":"Find the operating efficiency.","answer":"η = 22 ÷ 25.16 = 87.44%.","explain":"Efficiency is shaft output divided by total input."}],"order":4270},
{"id":"p4-b05-037","paper":4,"topic":"Motor Performance and VSD","kind":"problem","front":"A 2-pole, 50 Hz, 415 V motor rated 22 kW has nameplate speed 2980 rpm. At 423 V it runs at 2990 rpm. What is its actual output power?","back":"About 52% load, so about 11.4 kW output.","explain":"This review question is not worked in the book. The answer applies the book's voltage-compensated slip formula to its data.","flash":false,"source":"BEE Book 4 Ch 05 p119","steps":[{"prompt":"Find the synchronous speed.","answer":"Ss = 120 × 50 ÷ 2 = 3000 rpm.","explain":"A 2-pole motor on 50 Hz runs at 3000 rpm synchronous."},{"prompt":"Find the measured and nameplate slips.","answer":"Measured slip = 3000 − 2990 = 10 rpm. Nameplate slip = 3000 − 2980 = 20 rpm.","explain":"Each slip is synchronous speed minus the relevant speed."},{"prompt":"Compute the voltage-compensated load.","answer":"(415 ÷ 423)² = 0.962. Load = 10 ÷ (20 × 0.962) × 100 = 51.9% ≈ 52%.","explain":"The voltage factor corrects the nameplate slip for the higher supply voltage."},{"prompt":"Convert to output power.","answer":"0.52 × 22 kW = 11.4 kW.","explain":"Load % applies to rated output."}],"order":4271},
{"id":"p4-b05-038","paper":4,"topic":"Motor Performance and VSD","kind":"problem","front":"The stator winding resistance is 0.264 Ω per phase at 30 °C. What is it at 100 °C?","back":"About 0.334 Ω per phase.","explain":"This review question uses the book's resistance correction formula. It is not worked in the book, so the answer comes from the formula.","flash":false,"source":"BEE Book 4 Ch 05 p119","steps":[{"prompt":"Identify the two temperatures.","answer":"t₁ = 30 °C (reference), t₂ = 100 °C (operating).","explain":"The formula uses ambient or reference temperature as t₁ and operating temperature as t₂."},{"prompt":"Compute the temperature factor.","answer":"(235 + 100) ÷ (235 + 30) = 335 ÷ 265 = 1.264.","explain":"The 235 constant is the book's copper temperature term."},{"prompt":"Compute the corrected resistance.","answer":"R₂ = 0.264 × 1.264 = 0.334 Ω per phase.","explain":"Resistance rises with temperature, so the corrected value is higher."}],"order":4272},
{"id":"p4-b05-039","paper":4,"topic":"Motor Performance and VSD","kind":"problem","front":"Slip is 4%. Stator input is 3000 W, stator I²R loss 100 W and core loss 50 W. What are the rotor I²R losses?","back":"114 W.","explain":"This review question applies the book's rotor loss rule. It is not worked in the book, so the answer comes from the formula.","flash":false,"source":"BEE Book 4 Ch 05 p119","steps":[{"prompt":"Find the power left after stator losses.","answer":"3000 − 100 − 50 = 2850 W.","explain":"Stator I²R and core loss are subtracted from stator input."},{"prompt":"Apply the rotor loss rule.","answer":"Rotor I²R = slip × (stator input − stator I²R − core loss).","explain":"This is the book's method for rotor losses from slip."},{"prompt":"Calculate the rotor loss.","answer":"0.04 × 2850 = 114 W.","explain":"A 4% slip on 2850 W gives 114 W of rotor loss."}],"order":4273},
{"id":"p4-b06-001","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"What is the purpose of a fan performance test on site?","back":"To determine, under actual operating conditions, the volume flow rate, the power input and the static pressure rise across the fan. These results show the actual flow resistance of the duct system.","explain":"Comparing these results with the supplier's design value shows how the actual duct system resistance differs from design.","flash":false,"source":"BEE Book 4 Ch 06 p123","order":4274}
]$cards$::jsonb);
